import { test } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import * as bytes from "./bytes.ts";

// Vectors are generated by ts/tools/gen-bytes-vectors from Go's real bytes package.

interface GoCase {
  args: unknown[];
  ret?: unknown;
  nil?: boolean;
  panic?: boolean;
}

interface BufferOp {
  op: string;
  s?: string;
  c?: number;
  r?: number;
  b?: string;
  n?: number;
  panic: boolean;
}

interface BufferSeq {
  ops: BufferOp[];
  bytes: string;
  string: string;
  len: number;
}

interface SliceScenario {
  name: string;
  base: string;
  ret: string;
}

interface Vectors {
  goVersion: string;
  functions: Record<string, GoCase[]>;
  buffer: BufferSeq[];
  slices: SliceScenario[];
}

const data: Vectors = JSON.parse(
  readFileSync(new URL("./testdata/bytes_vectors.json", import.meta.url), "utf8"),
);

function fromHex(h: string): Uint8Array {
  const out = new Uint8Array(h.length / 2);
  for (let i = 0; i < out.length; i++) {
    out[i] = parseInt(h.slice(2 * i, 2 * i + 2), 16);
  }
  return out;
}

function toHex(b: Uint8Array): string {
  return Array.from(b, (x) => x.toString(16).padStart(2, "0")).join("");
}

const H = (x: unknown): Uint8Array => fromHex(x as string);
const S = (x: unknown): string => x as string;
const N = (x: unknown): number => x as number;
const L = (x: unknown): Uint8Array[] => (x as string[]).map(fromHex);
const LH = (xs: Uint8Array[]): string[] => xs.map(toHex);

// Each entry maps the JSON args of a vector to the JSON form of Go's result.
const impl: Record<string, (a: unknown[]) => unknown> = {
  ReplaceAll: (a) => toHex(bytes.ReplaceAll(H(a[0]), H(a[1]), H(a[2]))),
  Replace: (a) => toHex(bytes.Replace(H(a[0]), H(a[1]), H(a[2]), N(a[3]))),
  HasPrefix: (a) => bytes.HasPrefix(H(a[0]), H(a[1])),
  HasSuffix: (a) => bytes.HasSuffix(H(a[0]), H(a[1])),
  TrimPrefix: (a) => toHex(bytes.TrimPrefix(H(a[0]), H(a[1]))),
  TrimSuffix: (a) => toHex(bytes.TrimSuffix(H(a[0]), H(a[1]))),
  CutPrefix: (a) => {
    const [after, found] = bytes.CutPrefix(H(a[0]), H(a[1]));
    return { after: toHex(after), found };
  },
  TrimSpace: (a) => toHex(bytes.TrimSpace(H(a[0]))),
  Contains: (a) => bytes.Contains(H(a[0]), H(a[1])),
  Index: (a) => bytes.Index(H(a[0]), H(a[1])),
  LastIndex: (a) => bytes.LastIndex(H(a[0]), H(a[1])),
  Count: (a) => bytes.Count(H(a[0]), H(a[1])),
  Equal: (a) => bytes.Equal(H(a[0]), H(a[1])),
  EqualFold: (a) => bytes.EqualFold(H(a[0]), H(a[1])),
  Repeat: (a) => toHex(bytes.Repeat(H(a[0]), N(a[1]))),
  IndexByte: (a) => bytes.IndexByte(H(a[0]), N(a[1])),
  LastIndexByte: (a) => bytes.LastIndexByte(H(a[0]), N(a[1])),
  Split: (a) => LH(bytes.Split(H(a[0]), H(a[1]))),
  SplitN: (a) => LH(bytes.SplitN(H(a[0]), H(a[1]), N(a[2]))),
  SplitAfter: (a) => LH(bytes.SplitAfter(H(a[0]), H(a[1]))),
  ToLower: (a) => toHex(bytes.ToLower(H(a[0]))),
  Trim: (a) => toHex(bytes.Trim(H(a[0]), S(a[1]))),
  TrimLeft: (a) => toHex(bytes.TrimLeft(H(a[0]), S(a[1]))),
  TrimRight: (a) => toHex(bytes.TrimRight(H(a[0]), S(a[1]))),
  ContainsAny: (a) => bytes.ContainsAny(H(a[0]), S(a[1])),
  IndexAny: (a) => bytes.IndexAny(H(a[0]), S(a[1])),
  Join: (a) => toHex(bytes.Join(L(a[0]), H(a[1]))),
};

for (const [name, cases] of Object.entries(data.functions)) {
  test(`${name} matches ${cases.length} Go vectors`, () => {
    const f = impl[name];
    assert.ok(f, `no implementation for ${name}`);
    cases.forEach((c, i) => {
      const label = `${name}[${i}] args=${JSON.stringify(c.args)}`;
      if (c.panic) {
        assert.throws(() => f(c.args), RangeError, label);
        return;
      }
      assert.deepStrictEqual(f(c.args), c.ret, label);
    });
  });
}

test("every vector function has an implementation, and vice versa", () => {
  assert.deepStrictEqual(
    Object.keys(data.functions).sort(),
    Object.keys(impl).sort(),
  );
});

test("vector counts meet the minimum of 40 per function", () => {
  for (const [name, cases] of Object.entries(data.functions)) {
    assert.ok(cases.length >= 40, `${name} has ${cases.length} vectors`);
  }
});

test("Buffer operation sequences match Go", () => {
  data.buffer.forEach((seq, si) => {
    const b = new bytes.Buffer();
    seq.ops.forEach((op, oi) => {
      const run = (): void => {
        switch (op.op) {
          case "WriteString":
            b.WriteString(op.s as string);
            return;
          case "WriteByte":
            b.WriteByte(op.c as number);
            return;
          case "WriteRune":
            b.WriteRune(op.r as number);
            return;
          case "Write":
            b.Write(fromHex(op.b as string));
            return;
          case "Truncate":
            b.Truncate(op.n as number);
            return;
          case "Reset":
            b.Reset();
            return;
          case "Grow":
            b.Grow(op.n as number);
            return;
        }
        throw new Error(`unknown op ${op.op}`);
      };
      const label = `seq ${si} op ${oi} ${op.op}`;
      if (op.panic) {
        assert.throws(run, RangeError, label);
      } else {
        run();
      }
    });
    assert.equal(toHex(b.Bytes()), seq.bytes, `seq ${si} bytes`);
    assert.equal(b.String(), seq.string, `seq ${si} string`);
    assert.equal(b.Len(), seq.len, `seq ${si} len`);
  });
});

// ---- Hand-written tests: sub-slice views vs fresh allocations ----

const input = (s: string): Uint8Array => new TextEncoder().encode(s);

test("sub-slice results are views of the input buffer", () => {
  const s = input("  \tabc　  ");
  assert.equal(bytes.TrimSpace(s).buffer, s.buffer);
  assert.equal(toHex(bytes.TrimSpace(s)), toHex(input("abc")));

  const p = input("prefix-body-suffix");
  assert.equal(bytes.TrimPrefix(p, input("prefix-")).buffer, p.buffer);
  assert.equal(bytes.TrimSuffix(p, input("-suffix")).buffer, p.buffer);
  assert.equal(bytes.TrimLeft(p, "pr").buffer, p.buffer);
  assert.equal(bytes.TrimRight(p, "xif").buffer, p.buffer);
  assert.equal(bytes.Trim(p, "pxif").buffer, p.buffer);
  const [after, found] = bytes.CutPrefix(p, input("prefix"));
  assert.equal(found, true);
  assert.equal(after.buffer, p.buffer);

  const parts = bytes.Split(input("a,b,c"), input(","));
  assert.equal(parts.length, 3);
  for (const part of parts) {
    assert.equal(part.buffer, parts[0]?.buffer);
  }
  assert.deepStrictEqual(LH(bytes.SplitAfter(input("a,b"), input(","))), ["612c", "62"]);
  const sn = input("x|y|z");
  for (const part of bytes.SplitN(sn, input("|"), 2)) {
    assert.equal(part.buffer, sn.buffer);
  }
});

test("allocating results are fresh arrays", () => {
  const s = input("hello");
  assert.notEqual(bytes.ReplaceAll(s, input("zz"), input("y")).buffer, s.buffer);
  assert.notEqual(bytes.ToLower(s).buffer, s.buffer);
  assert.notEqual(bytes.Repeat(s, 2).buffer, s.buffer);
  assert.notEqual(bytes.Join([s], input(",")).buffer, s.buffer);
  assert.notEqual(bytes.Replace(s, input("l"), input("L"), 0).buffer, s.buffer);
});

test("Go edge cases on empty results and separators", () => {
  assert.deepStrictEqual(bytes.Split(input(""), input("")), []);
  assert.deepStrictEqual(LH(bytes.Split(input(""), input("a"))), [""]);
  assert.deepStrictEqual(bytes.SplitN(input("a,b"), input(","), 0), []);
  assert.deepStrictEqual(LH(bytes.Split(input("中a"), input(""))), ["e4b8ad", "61"]);
  assert.deepStrictEqual(LH(bytes.Split(new Uint8Array([0x61, 0xff, 0x62]), input(""))), ["61", "ff", "62"]);
  assert.equal(bytes.Count(input(""), input("")), 1);
  assert.equal(bytes.Count(input("中"), input("")), 2);
  assert.equal(bytes.Index(input("abc"), input("")), 0);
  assert.equal(bytes.LastIndex(input("abc"), input("")), 3);
  assert.equal(toHex(bytes.ReplaceAll(input("abc"), input(""), input("-"))), toHex(input("-a-b-c-")));
  assert.equal(toHex(bytes.Replace(input("abc"), input(""), input("-"), 2)), toHex(input("-a-bc")));
  assert.equal(toHex(bytes.ToLower(new Uint8Array([0x41, 0xff, 0x42]))), "61efbfbd62");
  assert.equal(toHex(bytes.Join([], input(","))), "");
  assert.equal(toHex(bytes.Join([input("a")], input(","))), "61");
});

test("Repeat panics for negative counts and returns empty for zero", () => {
  assert.throws(() => bytes.Repeat(input("a"), -1), RangeError);
  assert.equal(bytes.Repeat(input(""), 5).length, 0);
  assert.equal(toHex(bytes.Repeat(input("ab"), 3)), toHex(input("ababab")));
});

test("TrimSpace treats U+0085, U+00A0 and U+3000 as white space", () => {
  assert.equal(toHex(bytes.TrimSpace(input("\u0085x\u0085"))), toHex(input("x")));
  assert.equal(toHex(bytes.TrimSpace(input(" x "))), toHex(input("x")));
  assert.equal(toHex(bytes.TrimSpace(input("　x　"))), toHex(input("x")));
  assert.equal(bytes.TrimSpace(new Uint8Array([0x85])).length, 1);
});

test("EqualFold uses simple folding (Kelvin sign and long s)", () => {
  assert.equal(bytes.EqualFold(input("k"), input("K")), true);
  assert.equal(bytes.EqualFold(input("s"), input("ſ")), true);
  assert.equal(bytes.EqualFold(input("Straße"), input("STRASSE")), false);
  assert.equal(bytes.EqualFold(new Uint8Array([0xff]), new Uint8Array([0xff])), true);
  assert.equal(bytes.EqualFold(input("abc"), input("ab")), false);
});

test("HasPrefixAt and IndexByteFrom (port additions)", () => {
  const s = input("abcabc");
  assert.equal(bytes.HasPrefixAt(s, 3, input("abc")), true);
  assert.equal(bytes.HasPrefixAt(s, 4, input("abc")), false);
  assert.equal(bytes.HasPrefixAt(s, 6, input("")), true);
  assert.equal(bytes.HasPrefixAt(s, 7, input("")), false);
  assert.equal(bytes.HasPrefixAt(s, -1, input("a")), false);
  assert.equal(bytes.IndexByteFrom(s, 0x62, 2), 4);
  assert.equal(bytes.IndexByteFrom(s, 0x7a, 0), -1);
});

test("IndexAny and ContainsAny with empty or multibyte sets", () => {
  assert.equal(bytes.IndexAny(input("abc"), ""), -1);
  assert.equal(bytes.ContainsAny(input("abc"), ""), false);
  assert.equal(bytes.IndexAny(input("x中y"), "y中"), 1);
  assert.equal(bytes.IndexAny(new Uint8Array([0x61, 0xff]), "�"), 1);
});

// ---- Buffer ----

test("Buffer.WriteString encodes surrogate pairs and lone surrogates", () => {
  const b = new bytes.Buffer();
  assert.equal(b.WriteString("😀"), 4);
  assert.equal(toHex(b.Bytes()), "f09f9880");
  b.Reset();
  assert.equal(b.WriteString("\uD800x\uDC00"), 7);
  assert.equal(toHex(b.Bytes()), "efbfbd78efbfbd");
  b.Reset();
  b.WriteString("中é\u0000");
  assert.equal(toHex(b.Bytes()), "e4b8adc3a900");
});

test("Buffer.WriteRune encodes runes and maps invalid ones to U+FFFD", () => {
  const b = new bytes.Buffer();
  assert.equal(b.WriteRune(0x41), 1);
  assert.equal(b.WriteRune(0x4e2d), 3);
  assert.equal(b.WriteRune(-1), 3);
  assert.equal(b.WriteRune(0xd800), 3);
  assert.equal(b.WriteRune(0x110000), 3);
  assert.equal(toHex(b.Bytes()), "41" + "e4b8ad" + "efbfbd" + "efbfbd" + "efbfbd");
});

test("Buffer.String replaces each invalid byte with one U+FFFD", () => {
  assert.equal(new bytes.Buffer().String(), "");
  assert.equal(bytes.NewBuffer(new Uint8Array([0xe4, 0xb8])).String(), "��");
  assert.equal(bytes.NewBuffer(new Uint8Array([0xff, 0x41])).String(), "�A");
  assert.equal(bytes.NewBufferString("﻿x").String(), "﻿x");
  assert.equal(bytes.NewBufferString("中文").String(), "中文");
});

test("Buffer.Bytes aliases storage until the next write", () => {
  const b = new bytes.Buffer();
  b.WriteString("abc");
  const v = b.Bytes();
  assert.equal(v.buffer, b.arr.buffer);
  assert.equal(toHex(v), "616263");
  b.Truncate(1);
  assert.equal(toHex(b.Bytes()), "61");
});

test("NewBuffer adopts the caller's spare capacity", () => {
  const arr = new Uint8Array(8);
  const b = bytes.NewBuffer(arr.subarray(0, 0));
  assert.equal(b.Cap(), 8);
  b.WriteString("hi");
  assert.equal(arr[0], 0x68);
  assert.equal(arr[1], 0x69);
  assert.equal(b.Len(), 2);
});

test("Buffer.Truncate and Reset", () => {
  const b = bytes.NewBufferString("hello");
  assert.throws(() => b.Truncate(-1), RangeError);
  assert.throws(() => b.Truncate(6), RangeError);
  b.Truncate(3);
  assert.equal(b.String(), "hel");
  const cap = b.Cap();
  b.Reset();
  assert.equal(b.Len(), 0);
  assert.equal(b.Cap(), cap, "Reset keeps storage");
  b.WriteString("xy");
  b.Truncate(0);
  assert.equal(b.Len(), 0);
});

test("Buffer.Grow reserves capacity and rejects negative counts", () => {
  const b = new bytes.Buffer();
  b.Grow(100);
  assert.ok(b.Cap() >= 100);
  b.WriteString("x");
  assert.ok(b.Cap() >= 100);
  assert.throws(() => b.Grow(-1), RangeError);
});

test("Buffer.Write returns the byte count and handles self-aliasing", () => {
  const b = new bytes.Buffer();
  assert.equal(b.Write(input("abc")), 3);
  assert.equal(b.Write(b.Bytes()), 3);
  assert.equal(b.String(), "abcabc");
  assert.equal(b.WriteByte(0x21), undefined);
  assert.equal(b.String(), "abcabc!");
});

test("cutsets with astral code points trim whole code points", () => {
  const enc = new TextEncoder();
  const dec = new TextDecoder();
  const s = enc.encode("😀a😀");
  assert.equal(dec.decode(bytes.Trim(s, "😀")), "a");
  assert.equal(dec.decode(bytes.TrimLeft(s, "😀")), "a😀");
  assert.equal(dec.decode(bytes.TrimRight(s, "x😀")), "😀a");
  assert.equal(bytes.IndexAny(s, "a"), 4);
});
